From 7fe308d617f0b2e047c25af3b1168e00a683bc5b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:27:13 +0100
Subject: [PATCH] shell/panelview: Tell popups where side panels really are

Side panels assumed they started at the top of the screen, while the
compositor lays them out below top panels, so their tooltips and popups
opened shifted up by the top panel's height. Account for those panels.

BUG: 518087
---
 shell/panelview.cpp | 53 ++++++++++++++++++++++++++++++++++++++++++---
 shell/panelview.h   |  1 +
 shell/shellcorona.h |  5 +++++
 3 files changed, 56 insertions(+), 3 deletions(-)

diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..4b0a066b78 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -112,6 +112,18 @@ PanelView::PanelView(ShellCorona *corona, QScreen *targetScreen, QWindow *parent
         qCWarning(PLASMASHELL) << "Invalid home screen package";
     }

+    connect(m_layerWindow, &LayerShellQt::Window::exclusionZoneChanged, this, [this]() {
+        if (formFactor() != Plasma::Types::Horizontal) {
+            return;
+        }
+        const auto panels = m_corona->panelViews();
+        for (PanelView *panel : panels) {
+            if (panel->formFactor() == Plasma::Types::Vertical && panel->m_screenToFollow == m_screenToFollow && panel->containment()) {
+                panel->setPosition(panel->compositorPosition());
+            }
+        }
+    });
+
     m_strutsTimer.setSingleShot(true);
     connect(&m_strutsTimer, &QTimer::timeout, this, &PanelView::updateExclusiveZone);

@@ -648,7 +660,7 @@ void PanelView::positionPanel()
     updateLayerWindow();

     // TODO: should we remove this? It's still relevant on wayland because of popup positioning.
-    const QPoint pos = geometryByDistance(0).topLeft();
+    const QPoint pos = compositorPosition();
     setPosition(pos);
     updateMask();
     Q_EMIT geometryChanged();
@@ -673,7 +685,7 @@ void PanelView::positionAndResizePanel()
     }

     // TODO: can be removed? It's still relevant on wayland because of popup positioning.
-    const QPoint pos = geometryByDistance(0).topLeft();
+    const QPoint pos = compositorPosition();

     const QRect geom = {pos, sizeHint};
     bool geomChanged = geom != geometry();
@@ -708,6 +720,41 @@ QRect PanelView::dogdeGeometryByDistance(int distance) const
     return dodgeGeometry & m_screenToFollow->geometry();
 }

+QPoint PanelView::compositorPosition() const
+{
+    QRect geometry = geometryByDistance(0);
+    if (formFactor() != Plasma::Types::Vertical || !m_screenToFollow) {
+        return geometry.topLeft();
+    }
+
+    // The compositor lays out side panels in the space left by the top and bottom panels that fill the screen's width
+    int top = 0;
+    int bottom = 0;
+    const auto panels = m_corona->panelViews();
+    for (const PanelView *panel : panels) {
+        if (panel->formFactor() != Plasma::Types::Horizontal || panel->m_screenToFollow != m_screenToFollow || panel->m_lengthMode != FillAvailable
+            || !panel->isVisible() || panel->m_layerWindow->exclusionZone() <= 0) {
+            continue;
+        }
+        if (panel->location() == Plasma::Types::TopEdge) {
+            top += panel->m_layerWindow->exclusionZone();
+        } else {
+            bottom += panel->m_layerWindow->exclusionZone();
+        }
+    }
+
+    if (m_lengthMode == PanelView::LengthMode::FillAvailable) {
+        geometry.moveTop(m_screenToFollow->geometry().top() + top);
+    } else if (m_alignment == Qt::AlignLeft) {
+        geometry.translate(0, top);
+    } else if (m_alignment == Qt::AlignRight) {
+        geometry.translate(0, -bottom);
+    } else {
+        geometry.translate(0, (top - bottom) / 2);
+    }
+    return geometry.topLeft();
+}
+
 QRect PanelView::geometryByDistance(int distance) const
 {
     if (!containment() || !m_screenToFollow) {
@@ -1004,7 +1051,7 @@ void PanelView::resizeEvent(QResizeEvent *ev)
     if (m_screenToFollow && containment()) {
         updateEnabledBorders();
         // TODO: Can be removed? It's still relevant on wayland because of popup positioning.
-        const QPoint pos = geometryByDistance(0).topLeft();
+        const QPoint pos = compositorPosition();
         setPosition(pos);
         Q_EMIT m_corona->availableScreenRegionChanged(containment()->screen());

diff --git a/shell/panelview.h b/shell/panelview.h
index eb276bf7f6..3e232e38a1 100644
--- a/shell/panelview.h
+++ b/shell/panelview.h
@@ -317,6 +317,7 @@ private:
     void updateLayerWindow();
     void positionPanel();
     void positionAndResizePanel();
+    QPoint compositorPosition() const;
     void updateThickness();
     void integrateScreen();
     void updateEditModeLabel();
diff --git a/shell/shellcorona.h b/shell/shellcorona.h
index a85cd9aa07..9c7adfc99a 100644
--- a/shell/shellcorona.h
+++ b/shell/shellcorona.h
@@ -236,6 +236,11 @@ public Q_SLOTS:
         return m_panelViews.count();
     }

+    QList<PanelView *> panelViews() const
+    {
+        return m_panelViews.values();
+    }
+
 protected Q_SLOTS:
     /**
      * Loads the layout and performs the needed checks
